target.css:
:root {
  --ink: #29251f;
  --paper: #fffaf0;
  --line: #dfd3bd;
  --amber: #cf7b3c;
  --rose: #c96a74;
  --green: #718a54;
  --cream: #f5ead4;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.tasting-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--amber);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 22px;
  line-height: 1.1;
}

.leaf-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  background: var(--cream);
  border-radius: 50%;
  font-size: 19px;
}

.flight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 14px 18px;
}

.tea {
  min-width: 0;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.tea-amber {
  border-top: 4px solid var(--amber);
}

.tea-rose {
  border-top: 4px solid var(--rose);
}

.tea-green {
  border-top: 4px solid var(--green);
}

.cup {
  display: inline-block;
  margin-bottom: 12px;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

h2 {
  margin-bottom: 4px;
  font-size: 14px;
  line-height: 1.15;
}

.tea p {
  color: var(--ink);
  font-size: 11px;
  line-height: 1.3;
  opacity: 0.65;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  background: var(--cream);
}

.seat {
  font-size: 12px;
  font-weight: 600;
}

button {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 12px;
  color: var(--white);
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

button span {
  font-size: 16px;
  line-height: 0.7;
}

